import {useEffect,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {z} from 'zod';
import {candidateReviewEntry,candidateReviewHistory,candidateRejectionHistory,candidateHumanResult,candidateRejectionResult,recordCandidateReviewInput,recordCandidateRejectionInput,ids,artifactRef,strongETag} from '@devmesh/contracts';

type Entry=ReturnType<typeof candidateReviewEntry.parse>;
type Item=Entry['review']['items'][number];
type Rejection=ReturnType<typeof candidateRejectionResult.parse>;
type ReviewBody=ReturnType<typeof recordCandidateReviewInput.parse>;
type RejectBody=ReturnType<typeof recordCandidateRejectionInput.parse>;
const pendingSchema=z.discriminatedUnion('kind',[
  z.strictObject({kind:z.literal('review'),key:z.uuid(),candidateId:ids.candidate,ifMatch:strongETag,body:recordCandidateReviewInput}),
  z.strictObject({kind:z.literal('rejection'),key:z.uuid(),candidateId:ids.candidate,ifMatch:strongETag,body:recordCandidateRejectionInput}),
]);
type Pending=ReturnType<typeof pendingSchema.parse>;
const labels:Record<Item['status'],string>={PASS:'已通过',FAIL:'未通过',MISSING:'待检查',STALE:'依据已过期'};
const kinds:Record<Item['kind'],string>={requirement:'需求验收', 'work-human':'工作人工检查','quality-human':'质量人工检查'};
const time=(value:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
class ApiError extends Error{constructor(readonly status:number){super('Review request unavailable');}}
function references(form:FormData){const lines=String(form.get('evidence')??'').trim();return z.array(artifactRef).max(16).parse(lines?lines.split(/\r?\n/).filter(Boolean).map(line=>{const [artifactId,sha256,...extra]=line.trim().split(/\s+/);if(extra.length)throw Error('Invalid reference');return {artifactId,sha256};}):[]);}

function ResultForm({item,manifestHash,disabled,save}:{item:Item;manifestHash:string;disabled:boolean;save:(body:ReviewBody)=>void}){
  const [error,setError]=useState('');
  return <form onSubmit={event=>{event.preventDefault();try{const form=new FormData(event.currentTarget);const body=recordCandidateReviewInput.parse({manifestHash,itemId:item.itemId,itemHash:item.itemHash,previousResultId:item.result?.resultId??null,verdict:form.get('verdict'),procedure:form.get('procedure'),expected:item.expected,observed:form.get('observed'),evidence:references(form)});setError('');save(body);}catch{setError('请完整填写结论、实际操作和观察；证据每行填写一个材料 ID 与 SHA-256。');}}}>
    <label>检查结论<select name="verdict" defaultValue="" required disabled={disabled}><option value="" disabled>请选择实际结论</option><option value="PASS">通过</option><option value="FAIL">未通过</option></select></label>
    <label>实际操作<textarea name="procedure" maxLength={4096} required disabled={disabled}/></label>
    <label>实际观察<textarea name="observed" maxLength={4096} required disabled={disabled}/></label>
    <label>证据引用（可选）<textarea name="evidence" maxLength={4096} disabled={disabled} placeholder="artifact_… SHA-256，每行一项"/></label>
    {error&&<p role="alert">{error}</p>}<div className="actions"><button className="primary" disabled={disabled} type="submit">保存本项结论</button></div>
  </form>;
}

function RejectForm({items,manifestHash,original,disabled,withdrawOnly,save}:{items:Item[];manifestHash:string;original?:Rejection;disabled:boolean;withdrawOnly:boolean;save:(body:RejectBody)=>void}){
  const [error,setError]=useState('');
  return <form onSubmit={event=>{event.preventDefault();try{const form=new FormData(event.currentTarget),state=form.get('state')??'OPEN',selected=items.find(i=>i.itemId===form.get('itemId')),withdrawn=state==='WITHDRAWN';const body=recordCandidateRejectionInput.parse({manifestHash:original?.manifestHash??manifestHash,rejectionId:original?.rejectionId??'rejection_'+crypto.randomUUID().replaceAll('-',''),previousResultId:original?.resultId??null,classification:withdrawn?original?.classification:form.get('classification'),state,itemId:withdrawn?original?.item?.itemId??null:selected?.itemId??null,itemHash:withdrawn?original?.item?.itemHash??null:selected?.itemHash??null,description:withdrawn?original?.description:form.get('description'),reason:form.get('reason'),evidence:references(form)});if(body.classification==='IN_SCOPE_DEFECT'&&!body.itemId)throw Error('Item required');setError('');save(body);}catch{setError('请填写分类、问题和理由；原范围缺陷须关联审查项，证据每行填写材料 ID 与 SHA-256。');}}}>
    {original&&<label>本次处理<select name="state" defaultValue={withdrawOnly?'WITHDRAWN':'OPEN'} disabled={disabled}><option value="OPEN" disabled={withdrawOnly}>纠正分类或说明</option><option value="WITHDRAWN">有理由撤回退回</option></select></label>}
    {!withdrawOnly&&<><label>问题分类<select name="classification" defaultValue={original?.classification??''} required disabled={disabled}><option value="" disabled>请选择</option><option value="IN_SCOPE_DEFECT">原范围缺陷</option><option value="SCOPE_CHANGE">新增范围</option></select></label><label>关联审查项<select name="itemId" defaultValue={original?.item?.itemId??''} disabled={disabled}><option value="">无既有条目</option>{items.map((item,index)=><option key={item.itemId} value={item.itemId}>{index+1}. {item.expected.slice(0,80)}</option>)}</select></label><label>问题说明<textarea name="description" defaultValue={original?.description??''} maxLength={4096} required disabled={disabled}/></label></>}
    <label>本次理由<textarea name="reason" maxLength={4096} required disabled={disabled}/></label><label>证据引用（可选）<textarea name="evidence" maxLength={4096} disabled={disabled} placeholder="artifact_… SHA-256，每行一项"/></label>
    {error&&<p role="alert">{error}</p>}<div className="actions"><button className="primary" type="submit" disabled={disabled}>保存退回记录</button></div>
  </form>;
}

function Review({initial}:{initial:Entry}){
  const [entry,setEntry]=useState<Entry|null>(initial),[busy,setBusy]=useState(false),[stale,setStale]=useState(false),[denied,setDenied]=useState(false),[message,setMessage]=useState(''),[page,setPage]=useState(0),[abandon,setAbandon]=useState(false);
  const key='devmesh.candidateReview.pending:'+initial.runId;
  const [stored]=useState<{pending:Pending|null;invalid:boolean}>(()=>{try{const saved=sessionStorage.getItem(key);return {pending:saved?pendingSchema.parse(JSON.parse(saved)):null,invalid:false};}catch{return {pending:null,invalid:true};}});
  const [pending,setPending]=useState<Pending|null>(stored.pending),[invalidPending,setInvalidPending]=useState(stored.invalid);
  const [history,setHistory]=useState<{kind:'review'|'rejection';subjectId:string;candidateId:string;after:number;previous:number[];next:number|null;items:(ReturnType<typeof candidateHumanResult.parse>|Rejection)[]}|null>(null);
  const lock=useRef(false),disposed=useRef(false),controllers=useRef(new Set<AbortController>());
  const path=(candidateId:string)=>'/api/v1/runs/'+encodeURIComponent(initial.runId)+'/candidates/'+encodeURIComponent(candidateId)+'/review';
  useEffect(()=>{const stop=()=>{disposed.current=true;for(const c of controllers.current)c.abort();},restore=(event:PageTransitionEvent)=>{if(event.persisted)location.reload();};window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);return()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);};},[]);
  async function request(url:string,init:RequestInit={}){const controller=new AbortController();controllers.current.add(controller);try{const response=await fetch(url,{...init,credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.any([controller.signal,AbortSignal.timeout(15000)])});if(!response.ok)throw new ApiError(response.status);if(!response.headers.get('content-type')?.includes('application/json'))throw Error('Invalid response');return await response.json() as unknown;}finally{controllers.current.delete(controller);}}
  function failure(error:unknown){if(disposed.current)return;setStale(true);if(error instanceof ApiError&&[401,403,404].includes(error.status)){setDenied(true);setEntry(null);setHistory(null);setMessage('访问权限已失效，请重新进入或联系项目负责人。');}else if(error instanceof ApiError&&[409,412,422,428].includes(error.status)){setAbandon(true);setMessage('提交依据或填写内容已不适用。请刷新核对当前记录，再决定是否重新填写。');}else setMessage('暂时无法核实结果。请刷新状态；有待核实提交时使用原请求继续核实。');}
  async function run(action:()=>Promise<void>){if(lock.current||disposed.current)return;lock.current=true;setBusy(true);try{await action();}catch(error){failure(error);}finally{lock.current=false;if(!disposed.current)setBusy(false);}}
  async function load(){const next=candidateReviewEntry.parse(await request(path(initial.review.candidateId)));if(next.runId!==initial.runId||next.review.candidateId!==initial.review.candidateId)throw Error('Wrong review');if(disposed.current)return;setEntry(next);setHistory(null);setStale(false);setMessage('');}
  async function submit(original:Pending){
    const url=path(original.candidateId)+(original.kind==='review'?'/results':'/rejections'),result=await request(url,{method:'POST',headers:{'content-type':'application/json','idempotency-key':original.key,'if-match':original.ifMatch},body:JSON.stringify(original.body)});
    const parsed=original.kind==='review'?candidateHumanResult.parse(result):candidateRejectionResult.parse(result);if(parsed.candidateId!==original.candidateId||parsed.manifestHash!==original.body.manifestHash)throw Error('Wrong review result');
    if(disposed.current)return;sessionStorage.removeItem(key);setPending(null);setAbandon(false);await load();setMessage('原提交已核实并保存，当前审查已刷新。');
  }
  function save(kind:'review'|'rejection',body:ReviewBody|RejectBody,original?:Rejection){if(!entry||pending||invalidPending||stale||denied)return;void run(async()=>{const value=pendingSchema.parse({kind,key:crypto.randomUUID(),candidateId:original?.candidateId??entry.review.candidateId,ifMatch:'"r'+entry.review.resourceRevision+'"',body:{...body,manifestHash:original?.manifestHash??entry.review.manifestHash}});try{if(sessionStorage.getItem(key)!==null){setMessage('已有待核实记录，请刷新并核对原提交后继续。');return;}sessionStorage.setItem(key,JSON.stringify(value));}catch{setMessage('浏览器无法保存本次请求，请允许此站点使用会话存储后重试。');return;}setPending(value);setAbandon(false);await submit(value);});}
  async function readHistory(kind:'review'|'rejection',subjectId:string,candidateId:string,after=0,previous:number[]=[]){await run(async()=>{const value=await request(path(candidateId)+(kind==='review'?'/history?itemId=':'/rejections/history?rejectionId=')+encodeURIComponent(subjectId)+'&limit=20&afterSequence='+after),parsed=kind==='review'?candidateReviewHistory.parse(value):candidateRejectionHistory.parse(value);if(parsed.items.some(i=>i.result.candidateId!==candidateId||(kind==='review'?'item' in i.result&&i.result.item?.itemId!==subjectId:'rejectionId' in i.result&&i.result.rejectionId!==subjectId)))throw Error('Wrong history');if(!disposed.current)setHistory({kind,subjectId,candidateId,after,previous,next:parsed.nextSequence,items:parsed.items.map(i=>i.result)});});}
  const disabled=busy||stale||pending!==null||invalidPending||denied,review=entry?.review;
  return <main><nav className="row"><strong>DevMesh</strong><button onClick={()=>void run(load)} disabled={busy||denied}>刷新审查</button></nav><h1>逐项检查，再做决定。</h1><p className="muted">记录你在此候选上执行的操作与观察。人工审查保存后，版本仍需单独准备和接受。</p>
    {message&&<p className="notice" role="status">{message}</p>}
    {invalidPending&&!denied&&<section className="notice"><p>上次填写记录无法读取，请先核对当前审查和历史。</p><button disabled={busy||stale} onClick={()=>{try{sessionStorage.removeItem(key);setInvalidPending(false);setMessage('已清除无法读取的填写记录，请根据当前审查重新检查。');}catch{setMessage('无法清除本次填写，请检查浏览器会话存储。');}}}>核对后清除此填写记录</button></section>}
    {pending&&!denied&&<section className="notice" aria-label="待核实提交"><p>本次提交结果尚未核实。继续核实会找回原提交。</p><button disabled={busy} onClick={()=>void run(()=>submit(pending))}>核实原提交</button>{abandon&&<button disabled={busy||stale} onClick={()=>{try{sessionStorage.removeItem(key);setPending(null);setAbandon(false);setMessage('已放弃本次填写，请根据刷新后的记录重新检查。');}catch{setMessage('无法清除本次填写，请检查浏览器会话存储。');}}}>核对后放弃本次填写</button>}</section>}
    {entry&&review&&<><section className="version"><div className="row"><strong>{review.qualification==='CURRENT'?'当前候选':'已过期候选 · 只读审查'}</strong><span>人工审查：{labels[review.humanStatus]}</span></div><p className="commit">{entry.codeCommit}</p><p className="muted">必要项 {review.items.length} · 已通过 {review.items.filter(i=>i.status==='PASS').length} · 待检查 {review.items.filter(i=>i.status==='MISSING').length}</p>{review.canPrepareAcceptance&&<p>逐项审查已完成；此版本尚未接受。</p>}<p><a href={'/api/v1/runs/'+encodeURIComponent(entry.runId)+'/candidates/'+encodeURIComponent(review.candidateId)+'/acceptance/view'}>核对数据与接受准备</a></p><p><a href={'/api/v1/runs/'+encodeURIComponent(entry.runId)+'/candidates/'+encodeURIComponent(review.candidateId)+'/preview-management/view'}>准备数据与管理预览</a></p>{review.rejectionStatus==='OPEN'&&<p>仍有未处理的退回记录，不能准备接受。</p>}</section>
      <details><summary>原自动检查 · {review.automaticChecks.length} 项</summary>{review.automaticChecks.map((c,index)=><p key={index} className="commit">{c.checkId} · {c.status}</p>)}</details>
      <h2>必要人工检查</h2>{review.items.slice(page*20,page*20+20).map((item,index)=><article key={item.itemId} className="card" data-item-id={item.itemId}><div className="row"><h3>{page*20+index+1}. {kinds[item.kind]}</h3><span className={'badge '+item.status}>{labels[item.status]}</span></div><p className="expected">{item.expected}</p>{item.result&&<details><summary>当前人工记录 · {time(item.result.createdAt)}</summary><p>操作者：{item.result.principalId}</p><p>实际操作：{item.result.procedure}</p><p>实际观察：{item.result.observed}</p></details>}{review.canRecord&&<details><summary>{item.result?'修正本项结论':'记录本项结论'}</summary><ResultForm key={item.result?.resultId??'new'} item={item} manifestHash={review.manifestHash} disabled={disabled} save={body=>save('review',body)}/></details>}<button disabled={busy||denied} onClick={()=>void readHistory('review',item.itemId,review.candidateId)}>查看本项历史</button></article>)}
      {review.items.length>20&&<div className="pager"><button disabled={!page} onClick={()=>setPage(page-1)}>上一组</button><span>第 {page+1} 组</span><button disabled={(page+1)*20>=review.items.length} onClick={()=>setPage(page+1)}>下一组</button></div>}
      <h2>退回与范围分类</h2><p className="muted">原范围缺陷需要关联检查项；新增范围另行审查。保存退回不会自动实施修复或变更。</p>{review.canRecord&&<details className="card"><summary>新增退回</summary><RejectForm key={review.rejections.length} items={review.items} manifestHash={review.manifestHash} disabled={disabled} withdrawOnly={false} save={body=>save('rejection',body)}/></details>}{review.rejections.map(rejection=><article className="card" key={rejection.resultId}><div className="row"><strong>{rejection.classification==='IN_SCOPE_DEFECT'?'原范围缺陷':'新增范围'}</strong><span className="badge">{rejection.state==='OPEN'?'待处理':'已撤回'}</span></div><p>{rejection.description}</p><p className="muted">本次理由：{rejection.reason}</p><p className="muted">{rejection.state==='OPEN'?'等待后续审查处理':'本条已解除阻塞'} · {time(rejection.createdAt)}</p>{rejection.state==='OPEN'&&review.canWithdrawRejections&&<details><summary>纠正或撤回本条</summary><RejectForm original={rejection} items={review.items} manifestHash={review.manifestHash} disabled={disabled} withdrawOnly={!review.canRecord||rejection.candidateId!==review.candidateId} save={body=>save('rejection',body,rejection)}/></details>}<button disabled={busy||denied} onClick={()=>void readHistory('rejection',rejection.rejectionId,rejection.candidateId)}>查看退回历史</button></article>)}
    </>}
    {history&&!denied&&<section className="card" aria-label="记录历史"><div className="row"><h2>记录历史</h2><button onClick={()=>setHistory(null)}>收起历史</button></div>{!history.items.length&&<p>尚无历史记录。</p>}{history.items.map(result=><article key={result.resultId} className="history"><p>{time(result.createdAt)} · {result.principalId}</p>{'verdict' in result?<><p>{labels[result.verdict]}</p><p>实际操作：{result.procedure}</p><p>实际观察：{result.observed}</p></>:<><p>{result.state==='OPEN'?'退回':'撤回'} · {result.classification==='IN_SCOPE_DEFECT'?'原范围缺陷':'新增范围'}</p><p>{result.description}</p><p>{result.reason}</p></>}</article>)}<div className="pager"><button disabled={busy||!history.previous.length} onClick={()=>void readHistory(history.kind,history.subjectId,history.candidateId,history.previous.at(-1)??0,history.previous.slice(0,-1))}>上一页历史</button><button disabled={busy||history.next===null} onClick={()=>void readHistory(history.kind,history.subjectId,history.candidateId,history.next!,[...history.previous,history.after])}>下一页历史</button></div></section>}
  </main>;
}
const root=document.getElementById('root')!,data=document.getElementById('review-data');
try{createRoot(root).render(<Review initial={candidateReviewEntry.parse(JSON.parse(data?.textContent??''))}/>);}catch{root.textContent='审查无法加载，请刷新页面重试。';}
